contracts/Distributors.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./Manufacturers.sol";

contract Distributors {

    Manufacturer public manufacturerContract;

    struct Expedition {
        uint256 idExpedition;
        uint256 idMedicament;
        address fromManufacturers;
        address toPharmacy;
        string commentaire;
        bool produitRecu;
    }

     // Mappings
    mapping(uint => Expedition) public envoiMedicaments;
    mapping(address => bool) public distributeurAutorise;
    address public pharmacyAddress;

    // Variables
    uint256 public nbreExpedier;

    //Event
    event PackageEnvoye(uint256 indexed idEnvoi, address indexed fromFab, address indexed toDistr, uint256 envoiDate);
    event PackageRecu(uint256 indexed idEnvoi, address indexed distributeur);
    event DistributeurAutorise(address indexed distributeur);
    event DistributeurRevoke(address indexed distributeur);

    modifier onlyDistributeur{
        require (distributeurAutorise[msg.sender] == true, "Only the authorised distributeurs can call this function");
        _;
    }

    constructor(address _fabricantAddress) {
        manufacturerContract = Manufacturer(_fabricantAddress);
        distributeurAutorise[msg.sender] = true;
        nbreExpedier = 1;
    }

    //function pour autoriser les distributeurs
    function authorizeDistributeur(address _distributeur) public onlyDistributeur {
        require(_distributeur != address(0), "Invalid distributor address");
        distributeurAutorise[_distributeur] = true;
        emit DistributeurAutorise(_distributeur);
    }

    //function pour supprimer un distributeur
    function revokeDistributeur(address _distributeur) public onlyDistributeur {
        require(_distributeur != address(0), "Invalid distributor address");
        distributeurAutorise[_distributeur] = false;
        emit DistributeurRevoke(_distributeur);
    }

    // Ajouter un Distributeur
    function ajouterPharmacy(address _pharmacy) public onlyDistributeur {
        pharmacyAddress = _pharmacy;
    }

    function creerExpedition(uint256 _idMed, address _pharmacy, string memory _commentaire) public onlyDistributeur {
        require(_pharmacy != address(0), "Invalid pharmacy address");
        require(manufacturerContract.medicamentOwners(_idMed) != address(0), "Medicament does not exist");
        require(envoiMedicaments[_idMed].idExpedition == 0, "Expedition already exists");

        Expedition storage newEnvoi = envoiMedicaments[nbreExpedier];
        newEnvoi.idExpedition = nbreExpedier;
        newEnvoi.idMedicament = _idMed;
        newEnvoi.fromManufacturers = manufacturerContract.medicamentOwners(_idMed);
        newEnvoi.toPharmacy = _pharmacy;
        newEnvoi.commentaire = _commentaire;
        newEnvoi.produitRecu = false;


        emit PackageEnvoye(nbreExpedier, manufacturerContract.medicamentOwners(_idMed), _pharmacy, block.timestamp);
        nbreExpedier++;
         // Vérification du transfert
        bool transfertValide = verifierTransfertMedicament(_idMed);
        require(transfertValide, "Transfert du medicament non valide");
    }

    function markAsDelivered(uint256 _idExpedition) public {
        require(!envoiMedicaments[_idExpedition].produitRecu, "Produit deja delivre");
        envoiMedicaments[_idExpedition].produitRecu = true;
    }

    function verifierTransfertMedicament(uint256 _idMed) public view returns (bool) {
    // Vérifiez que l'ID du médicament est valide
    require(_idMed > 0 && _idMed <= manufacturerContract.medicamentCount(), "ID du medoc invalide");
    address distributeur = manufacturerContract.medicamentOwners(_idMed);
    return distributeur == msg.sender;
    }

    function getExpeditionDetails(uint256 _idExpedition) public view returns (
        uint256 idExpedition,
        uint256 idMedicament, address fromManufacturers,
        address toPharmacy, string memory commentaire, bool produitRecu) {
            require(_idExpedition > 0 && _idExpedition < nbreExpedier, "Invalid shipment ID");
            Expedition storage expedition = envoiMedicaments[_idExpedition];
            return (
                expedition.idExpedition, 
                expedition.idMedicament, 
                expedition.fromManufacturers, 
                expedition.toPharmacy, 
                expedition.commentaire, 
                expedition.produitRecu
            );
    }
}

contracts/Manufacturers.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;
//0xcAba93D84F9E1Eb8F90D38cBEad5f683F14c4b1b
//0xd9145CCE52D386f254917e481eB44e9943F39138 
contract Manufacturer {

    struct Medicament {
        uint256 idMedicament;
        string nom;
        string numeroSerie;
        string dateFabrication;
        string datePeremption;
        address fabricantsAddress;
        bool isActive;
    }
    //mappings
    mapping(uint256 => Medicament) public medicaments;
    mapping(address => bool) public fabricantAdmis;
    mapping(uint256 => address) public medicamentOwners;

    uint public medicamentCount = 0;
    address public distributeurAddress;

    //Events
    event MedicamentAjoute(uint256 indexed idMedicament,string nom, string numeroSerie);
    event FabricantAutorise(address indexed fabricants);
    event FabricantRevoque(address indexed fabricants);
    event AjoutDistributeur(address newDistributeur);
    event MedicamentTransfere(uint256 indexed idMedicament, address indexed from, address indexed to);

     //modifier pour vérifier si le fabricant est autorisé
    modifier onlyFabricant() {
        require(fabricantAdmis[msg.sender], "Fabricant non autorise");
        _;
    }

    //constructeur - La Personne qui déploie le contrat est autorisée
    constructor() {
        fabricantAdmis[msg.sender] = true;
        medicamentCount = 1;
    }

    //fonction pour authoriser un nouveau fabricants
    function autoriserFabricant(address _fabricantsAddress) public onlyFabricant {
        fabricantAdmis[_fabricantsAddress] = true;
        emit FabricantAutorise(_fabricantsAddress);
    }

    //function pour révoquer un fabricant
    function revoquerFabricant(address _fabricantsAddress) public onlyFabricant {
        fabricantAdmis[_fabricantsAddress] = false;
        emit FabricantRevoque(_fabricantsAddress);
    }

    // Ajouter un Distributeur
    function ajouterDistributeur(address _distributeur) public onlyFabricant {
        distributeurAddress = _distributeur;
        emit AjoutDistributeur(_distributeur);
    }

    function medicamentExists(uint256 _idMed) public view returns (bool) {
    return _idMed <= medicamentCount && medicamentOwners[_idMed] != address(0);
    }


    function ajouterMedicament (uint _id, string memory _nom, string memory _numSerie ,
        string memory _dateFab, string memory _datePeremption) public onlyFabricant returns(uint256){
        medicaments[medicamentCount] = Medicament({
            idMedicament: _id, 
            nom: _nom,
            numeroSerie: _numSerie,
            dateFabrication : _dateFab, 
            datePeremption : _datePeremption, 
            fabricantsAddress: msg.sender,
            isActive: true}); 
        medicamentOwners[medicamentCount] = msg.sender;
        medicamentCount ++;
        emit MedicamentAjoute(_id,_nom,_numSerie); 
        return medicamentCount;
        }

    function getMedicamentsInfo(uint256 _idMed) public view 
        returns (uint, string memory, string memory, string memory, string memory, address, bool) {
        require(_idMed <= medicamentCount, "ID du Medicament Invalide");
        Medicament memory medic = medicaments[_idMed];
        return (medic.idMedicament, medic.nom, medic.numeroSerie, medic.dateFabrication, medic.datePeremption, medic.fabricantsAddress, medic.isActive);
    }

    function rappelerMedicament(uint256 _idMed) public onlyFabricant{
        require(_idMed <= medicamentCount , "Numero de medicaments inexistants");
        require(medicaments[_idMed].fabricantsAddress == msg.sender, "Seul le fabricant peut rappeler le lot");
        require((bool)(medicaments[_idMed].isActive),"Medicament non present en stock");
        Medicament storage medicament = medicaments[_idMed];
        medicament.isActive=false;   
    }

    function transfererMedicament(uint256 _idMed, address _distributeur) public onlyFabricant {
        require(_idMed <= medicamentCount , "Numero de medicaments inexistants");
        require(medicamentOwners[_idMed] == msg.sender, "Vous n'etes pas le proprietaire du medicament");
        require((bool)(medicaments[_idMed].isActive),"Medicament non present en stock");

        medicaments[_idMed].fabricantsAddress = _distributeur; 
        medicamentOwners[_idMed] = _distributeur;
        emit MedicamentTransfere(_idMed, msg.sender,_distributeur);
    }
}

contracts/Patient.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./Pharmacy.sol";
import "./Distributors.sol";
import "./Manufacturers.sol";

contract Patient {

    Pharmacy public pharmacyContract;
    Distributors public distributorsContract;
    Manufacturer public manufacturerContract;

    struct Achat {
        uint256 idMedicament;
        uint256 quantite;
        address pharmacyAddress;
        uint256 dateAchat;
    }

    // Mappings
    mapping(address => bool) public patientAutorise;
    mapping(uint256 => Achat) public achats;
    mapping(uint256 => bool) public achatValide;

    // Variables
    uint256 public achatCount = 0;

    // Events
    event MedicamentAchete(uint256 indexed idMedicament, uint256 quantite, address indexed patient, address indexed pharmacy);
    event PatientAutorise(address indexed patient);
    event PatientRevoque(address indexed patient);

    modifier onlyPatient() {
        require(patientAutorise[msg.sender], "Patient non autorise");
        _;
    }

    constructor(address _pharmacyAddress, address _distributorAddress, address _manufacturerAddress) {
        pharmacyContract = Pharmacy(_pharmacyAddress);
        distributorsContract = Distributors(_distributorAddress);
        manufacturerContract = Manufacturer(_manufacturerAddress);
        patientAutorise[msg.sender] = true;
    }

    // Autoriser un patient
    function autoriserPatient(address _patient) public onlyPatient {
        patientAutorise[_patient] = true;
        emit PatientAutorise(_patient);
    }

    // Révoquer un patient
    function revoquerPatient(address _patient) public onlyPatient {
        patientAutorise[_patient] = false;
        emit PatientRevoque(_patient);
    }

    // Acheter un médicament
    function acheterMedicament(uint256 _idMedicament, uint256 _quantite) public onlyPatient {
        require(_quantite > 0, "Quantite invalide");

        (, uint256 quantite, bool isActive) = pharmacyContract.stockMedicaments(_idMedicament);
        require(quantite >= _quantite, "Stock insuffisant");
        require(isActive, "Medicament non disponible");

        pharmacyContract.vendreMedicament(_idMedicament, _quantite, msg.sender);

        achats[achatCount] = Achat({
            idMedicament: _idMedicament,
            quantite: _quantite,
            pharmacyAddress: pharmacyContract.medicamentOwners(_idMedicament),
            dateAchat: block.timestamp
        });

        achatValide[achatCount] = true;
        emit MedicamentAchete(_idMedicament, _quantite, msg.sender, pharmacyContract.medicamentOwners(_idMedicament));
        achatCount++;
    }

    // Vérifier la traçabilité d’un achat
    function verifierTracabilite(uint256 _idAchat) public view returns (bool, string memory) {
        require(achatValide[_idAchat], "Achat invalide");

        Achat memory achat = achats[_idAchat];
        uint256 idMedicament = achat.idMedicament;

        (,, bool isActive) = pharmacyContract.stockMedicaments(idMedicament);
        require(isActive, "Medicament non disponible");

        address pharmacy = achat.pharmacyAddress;
        (,, address fromManufacturers,,,) = distributorsContract.envoiMedicaments(idMedicament);
        address distributeur = fromManufacturers;
        address fabricant = manufacturerContract.medicamentOwners(idMedicament);

        string memory historique = string(
            abi.encodePacked(
                "Historique de transit:\n",
                "Fabricant: ", addressToString(fabricant), "\n",
                "Distributeur: ", addressToString(distributeur), "\n",
                "Pharmacie: ", addressToString(pharmacy), "\n"
            )
        );

        return (true, historique);
    }

    // Obtenir les détails d’un achat
    function getAchatDetails(uint256 _idAchat) public view returns (uint256, uint256, address, uint256) {
        require(achatValide[_idAchat], "Achat invalide");

        Achat memory achat = achats[_idAchat];
        return (achat.idMedicament, achat.quantite, achat.pharmacyAddress, achat.dateAchat);
    }

    // Utilitaire pour convertir une adresse en string
    function addressToString(address _addr) internal pure returns (string memory) {
        bytes32 value = bytes32(uint256(uint160(_addr)));
        bytes memory alphabet = "0123456789abcdef";

        bytes memory str = new bytes(42);
        str[0] = '0';
        str[1] = 'x';

        for (uint256 i = 0; i < 20; i++) {
            str[2 + i * 2] = alphabet[uint8(value[i + 12] >> 4)];
            str[3 + i * 2] = alphabet[uint8(value[i + 12] & 0x0f)];
        }

        return string(str);
    }
}

contracts/Pharmacy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./Distributors.sol";
//0x8461A3Ea5a60C5157F6887b830A25bA0D1cd044F
// 0x1bB5bf909d1200fb4730d899BAd7Ab0aE8487B0b
contract Pharmacy {
    Distributors public distributorsContract;

    struct Stock {
        uint256 idMedicament;
        uint256 quantite;
        bool isActive;
    }

    // Mappings
    mapping(uint256 => Stock) public stockMedicaments;
    mapping(address => bool) public pharmacieAutorisee;
    mapping(uint256 => address) public medicamentOwners;

    // Events
    event MedicamentRecu(uint256 indexed idMedicament, uint256 quantite, address indexed fromDistributeur);
    event MedicamentVendu(uint256 indexed idMedicament, uint256 quantite, address indexed toClient);
    event PharmacieAutorisee(address indexed pharmacie);
    event PharmacieRevoquee(address indexed pharmacie);

    modifier onlyPharmacie() {
        require(pharmacieAutorisee[msg.sender], "Pharmacie non autorisee");
        _;
    }

    constructor(address _distributeurAddress) {
        distributorsContract = Distributors(_distributeurAddress);
        pharmacieAutorisee[msg.sender] = true;
    }

    // Fonction pour recevoir un médicament
    function recevoirMedicament(uint256 _idMedicament, uint256 _quantite) public onlyPharmacie {
        require(_quantite > 0, "Quantite invalide");

        if (stockMedicaments[_idMedicament].quantite == 0) {
            stockMedicaments[_idMedicament] = Stock(_idMedicament, _quantite, true);
        } else {
            stockMedicaments[_idMedicament].quantite += _quantite;
        }

        medicamentOwners[_idMedicament] = msg.sender;
        distributorsContract.markAsDelivered(_idMedicament);
        emit MedicamentRecu(_idMedicament, _quantite, msg.sender);
    }

    // Fonction pour vendre un médicament
    function vendreMedicament(uint256 _idMedicament, uint256 _quantite, address _client) public {
        require(_quantite > 0, "Quantite invalide");
        require(stockMedicaments[_idMedicament].quantite >= _quantite, "Stock insuffisant");
        require(stockMedicaments[_idMedicament].isActive, "Medicament non disponible");

        stockMedicaments[_idMedicament].quantite -= _quantite;

        if (stockMedicaments[_idMedicament].quantite == 0) {
            stockMedicaments[_idMedicament].isActive = false;
        }

        emit MedicamentVendu(_idMedicament, _quantite, _client);
    }

    // Fonction pour obtenir les détails du stock d'un médicament
    function getStockDetails(uint256 _idMedicament) public view returns (uint256, uint256, bool) {
        require(stockMedicaments[_idMedicament].quantite > 0, "Medicament non disponible");
        Stock memory stock = stockMedicaments[_idMedicament];
        return (stock.idMedicament, stock.quantite, stock.isActive);
    }
}

